# DBTITLE 1,Comment for tables
table_comment = (
    "Standardized Note Exchange System (NES) dataset containing operational information "
    "generated by Currency\\'s Note Exchange System. The dataset includes deposit, withdrawal, "
    "shipment, capacity, counterfeit, and related operational data used for business reporting "
    "and analysis."
)

# COMMAND ----------

# DBTITLE 1,Create Standardized table - shortage
spark.sql(f"""
CREATE OR REPLACE TABLE {unity_catalog_name}.standardized_db.tbl_nes_shortage
(
nes_function STRING,
isa_link_id STRING,
transaction_id STRING,
denomination STRING,
note_type STRING,
withdrawal_entry_date TIMESTAMP,
shortage_date TIMESTAMP,
region_name STRING,
region_id STRING,
fi_name STRING,
fi_id STRING,
rdc_id STRING,
withdrawal_note_count DECIMAL(10,0),
shortage_note_count DECIMAL(38,0),
shortage_note_value INT,

audit_file_name STRING,
audit_file_date DATE,
audit_load_ts TIMESTAMP
)
USING DELTA
TBLPROPERTIES (
  'delta.deletedFileRetentionDuration' = 'interval 60 days',
  'delta.autoOptimize.optimizeWrite' = 'true',
  'delta.enableChangeDataFeed' = 'true'
)
COMMENT '{table_comment}';
""")

# COMMAND ----------

# DBTITLE 1,Adding table column comments - shortage
comments = {
# placeholder until until the data dictionary is finalized for the column descriptions
    
  "audit_file_name": "Source file name used for ingestion",
  "audit_file_date": "Source file date (YYYY-MM-DD)",
  "audit_load_ts": "Timestamp when the record was loaded into the table"
}

for col, comment in comments.items():
    spark.sql(f"""
    ALTER TABLE {unity_catalog_name}.standardized_db.tbl_nes_shortage
    ALTER COLUMN {col}
    COMMENT '{comment.replace("'", "''")}';
    """)

